window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[131]={"id":"131","numero":131,"titre":"Troubles de la marche et de l'équilibre du sujet âgé","objectifs":[{"id":"131-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le système antigravitaire, l’adaptation posturale, le système vestibulaire et la proprioception","contenu":"<p>La marche est une production motrice <span class=\"kw-def\">très automatisée</span> qui échappe largement au contrôle conscient. Son maintien repose sur l'intégrité de plusieurs systèmes que le vieillissement fragilise.</p>\n      <table >\n        <thead><tr><th>Système</th><th>Rôle et afférences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Système antigravitaire</span></td>\n            <td>Maintient l'<strong>attitude érigée</strong> en s'opposant à la <span class=\"kw-clinique\">pesanteur</span>. Dépend du <span class=\"kw-clinique\">tonus des muscles antigravitaires</span> (<span class=\"kw-clinique\">extenseurs des membres inférieurs</span>, <span class=\"kw-clinique\">muscles paravertébraux</span> — le <span class=\"kw-clinique\">triceps sural</span> est le seul muscle des MI actif en station debout). <strong>Afférences :</strong> <span class=\"kw-clinique\">plante des pieds</span>, <span class=\"kw-clinique\">labyrinthe</span> de l'oreille interne, <span class=\"kw-clinique\">récepteurs musculo-tendineux</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Système d'équilibre et d'adaptation posturale</span></td>\n            <td>Maintient la posture en intégrant <strong>3 modes de perception :</strong><br>• la <span class=\"kw-clinique\">vue</span> ;<br>• le <span class=\"kw-clinique\">système vestibulaire</span> (participe au tonus postural et renseigne sur la direction/vitesse du mouvement) ;<br>• <span class=\"kw-clinique\">les</span> voies <span class=\"kw-clinique\">proprioceptives</span> afférentes (position des articulations/membres ; afférences plantaires majeures, cheminant par les <span class=\"kw-def\">cordons postérieurs</span> de la moelle spinale).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Réaction d'équilibration</span></td>\n            <td>Mouvements compensatoires <strong>automatiques</strong> d'adaptation posturale (statiques et dynamiques). Nécessite l'intégrité du système antigravitaire, des voies <span class=\"kw-clinique\">cérébello-vestibulaires</span>, du contrôle moteur cérébral « de haut niveau », des voies motrices (<span class=\"kw-def\">pyramidale</span> et <span class=\"kw-def\">extrapyramidale</span>) et des effecteurs (muscles, articulations).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-clinique\">production du pas</span> est une activité rythmique en <span class=\"kw-clinique\">appui unipodal</span> alterné : une succession de <span class=\"kw-clinique\">ruptures d'équilibre</span> suivies de réactions qui restaurent la stabilité de chaque membre inférieur.</p>","frequence":1},{"id":"131-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la modification de la marche et de la posture induite par le vieillissement","contenu":"<p><span class=\"kw-clinique\">Les</span> réactions posturales se <strong>maintiennent</strong> au cours du vieillissement, mais leur <span class=\"kw-clinique\">vitesse</span> et les capacités d'adaptation aux situations extrêmes <strong>diminuent</strong>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Caractéristiques de la marche du sujet âgé</h4>\n      <ul>\n        <li>Augmentation des <span class=\"kw-clinique\">oscillations</span> à la station debout.</li>\n        <li>Diminution de la <span class=\"kw-clinique\">vitesse</span> de marche.</li>\n        <li><span class=\"kw-ttt\">Réduction</span> de la <span class=\"kw-clinique\">longueur</span> et de la <span class=\"kw-clinique\">hauteur</span> du pas.</li>\n        <li>Augmentation du <span class=\"kw-clinique\">temps de double appui</span>.</li>\n        <li>Variabilité du pas plus élevée ; diminution du <span class=\"kw-clinique\">ballant des bras</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Système</th><th>Déclin physiologique</th><th>Pathologies fréquentes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Proprioception</span></td><td>↓ nombre de récepteurs, ↓ vitesse de conduction et de l'influx (MI ≫ MS)</td><td><span class=\"kw-etio\">Diabète</span>, <span class=\"kw-etio\">carences vitaminiques</span> (B12, D…)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vision</span></td><td>↓ champ visuel, ↓ sensibilité au contraste, ↓ acuité visuelle</td><td><span class=\"kw-etio\">Cataracte</span>, <span class=\"kw-etio\">DMLA</span>, <span class=\"kw-etio\">glaucome chronique</span>, presbytie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vestibule</span></td><td>Mise au repos par défaut de stimulation ; rôle majeur si autre système déficitaire</td><td><span class=\"kw-etio\">VPPB</span> (<span class=\"kw-clinique\">vertige</span> positionnel paroxystique bénin)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Vieillir ne fait pas tomber</strong> — mais en présence d'un <span class=\"kw-etio\">facteur précipitant</span>, le risque de chute est bien plus important que chez le sujet jeune.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"131-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les tests de marche et de posture","contenu":"<p>Des tests standardisés (recommandés <span class=\"kw-bio\">HAS 2012</span>) dépistent une <span class=\"kw-clinique\">vulnérabilité à la marche</span> et quantifient le risque de chute, en <span class=\"kw-bio\">complément</span> de l'examen clinique.</p>\n      <table >\n        <thead><tr><th>Test</th><th>Réalisation et seuil pathologique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Station unipodale</span></td><td>Tenir debout sur un pied. <strong>Pathologique :</strong> &lt; <span class=\"kw-chiffre\">5 s</span> et/ou besoin d'<span class=\"kw-clinique\">écarter les bras</span> → très haut risque de chute ; &gt; <span class=\"kw-chiffre\">30 s</span> → risque très faible.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Timed Up and Go (TUG)</span></td><td>Se lever d'une chaise, marcher <span class=\"kw-chiffre\">3 m</span>, demi-tour, se rasseoir. <strong>Pathologique :</strong> &gt; <span class=\"kw-chiffre\">20 s</span> → risque de nouvelle chute.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Stop walking while talking</span></td><td>Tâche attentionnelle pendant la marche. <strong>Pathologique :</strong> arrêt de la marche pour répondre → risque accru de chute.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Five times sit-to-stand (FTSS)</span></td><td>Se lever/rasseoir 5 fois sans <span class=\"kw-clinique\">les</span> bras. <strong>Pathologique :</strong> &gt; <span class=\"kw-chiffre\">15 s</span> → risque de chute, <span class=\"kw-clinique\">faiblesse musculaire des MI</span>, <span class=\"kw-clinique\">trouble cognitif</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>Échelles complémentaires de quantification : <span class=\"kw-clinique\">échelle d'équilibre de Berg</span>, <span class=\"kw-clinique\">périmètre de marche</span>, <span class=\"kw-clinique\">vitesse sur 10 mètres</span>, <span class=\"kw-clinique\">test de marche de 6 minutes</span>, <span class=\"kw-clinique\">Functional Ambulation Classification</span>.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"131-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les troubles de la marche (voir aussi item 109)","contenu":"<p>Cet objectif renvoie aux <strong>grandes familles sémiologiques</strong> de troubles de la marche, détaillées dans l'<strong>item 109</strong>. À reconnaître pour orienter l'étiologie.</p>\n      <ul>\n        <li><strong>Ataxies</strong> (hors <span class=\"kw-clinique\">déficit moteur</span>) : <span class=\"kw-clinique\">proprioceptive</span> (Romberg aggravé yeux fermés, marche talonnante), <span class=\"kw-clinique\">vestibulaire</span> (latéralisée, marche aveugle « en étoile »), <span class=\"kw-clinique\">cérébelleuse</span> (polygone élargi, <span class=\"kw-alerte\">non aggravée à l'occlusion des yeux ⭐</span>).</li>\n        <li><strong>Troubles déficitaires</strong> : <span class=\"kw-clinique\">steppage</span> (déficit des releveurs), <span class=\"kw-clinique\">fauchage</span> (<span class=\"kw-def\">syndrome pyramidal</span>), boiterie de <span class=\"kw-clinique\">Trendelenburg</span>, <span class=\"kw-clinique\">marche dandinante</span>.</li>\n        <li><strong>Hypokinétiques (marche à petits pas)</strong> — <span class=\"kw-alerte\">trouble le plus fréquent (1/3 des cas)</span> : syndromes <span class=\"kw-etio\">parkinsoniens</span>, <span class=\"kw-etio\">hydrocéphalie chronique de l'adulte</span>, <span class=\"kw-etio\">états lacunaires</span>.</li>\n        <li><strong>Hyperkinétiques</strong> : <span class=\"kw-etio\">dystonie</span> (la plus pourvoyeuse), <span class=\"kw-etio\">chorée</span>, tremblements.</li>\n        <li><strong>Apraxie de la marche</strong> → <span class=\"kw-def\">astasie-abasie</span> ; causes <strong>douloureuses</strong> (boiterie d'esquive, <span class=\"kw-clinique\">claudication</span>) ; <span class=\"kw-clinique\">marches psychogènes</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 109 — Trouble marche - équilibre · 104 — SEP · 106 — Parkinson · 107 — Mouvements anormaux · 340 — <span class=\"kw-alerte\">AVC</span></em></p>","frequence":0},{"id":"131-5","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une chute et d’une chute à répétition (HAS)","contenu":"<p><strong>Il n'existe pas de chute banale chez la personne âgée.</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Chute</span> (OMS) : « le fait de se retrouver <strong>involontairement</strong> sur le sol ou dans une position de <strong>niveau inférieur</strong> par rapport à la position de départ ».</li>\n        <li><span class=\"kw-def\">Chute à répétition</span> : au moins <span class=\"kw-chiffre\">2 chutes</span> sur une période de <span class=\"kw-chiffre\">12 mois</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":1},{"id":"131-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","contenu":"<p>Chez la personne âgée, l'<span class=\"kw-clinique\">examen de la marche</span> est systématique (faire marcher nu-pieds en ligne droite + demi-tour) : il caractérise le trouble et oriente vers une origine <strong>neurologique</strong> ou <strong>douloureuse</strong>.</p>\n      <table >\n        <thead><tr><th>Tableau clinique</th><th>Localisation / cause</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Ataxique</span> — <span class=\"kw-clinique\">pseudo-ébrieuse</span></td><td><span class=\"kw-etio\">Cérébelleuse</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Ataxique</span> — <span class=\"kw-clinique\">talonnante</span></td><td><span class=\"kw-etio\">Proprioceptive</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Ataxique</span> — <span class=\"kw-clinique\">latéralisée / en étoile</span></td><td><span class=\"kw-etio\">Vestibulaire</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fauchage</span></td><td>Atteinte <span class=\"kw-def\">pyramidale</span> unilatérale</td></tr>\n          <tr><td><span class=\"kw-clinique\">Spasmodique</span> (en ciseaux)</td><td>Atteinte <span class=\"kw-def\">pyramidale</span> bilatérale</td></tr>\n          <tr><td><span class=\"kw-clinique\">Steppage</span></td><td>Loge antéro-externe de jambe (<span class=\"kw-etio\">L4-L5</span> ou <span class=\"kw-etio\">fibulaire commun</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dandinante</span></td><td>Ceinture pelvienne (déficit proximal)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Parkinsonienne</span></td><td>Petits pas, perte du ballant des bras, freezing, festination → <span class=\"kw-etio\">syndrome parkinsonien</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Apraxique</span> / <span class=\"kw-def\">astasie-abasie</span></td><td>Atteinte frontale, <span class=\"kw-etio\">hydrocéphalie à pression normale</span>, <span class=\"kw-etio\">état lacunaire</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Claudicante</span> (douloureuse)</td><td><span class=\"kw-etio\">AOMI</span>, cause médullaire</td></tr>\n          <tr><td><span class=\"kw-clinique\">Boiterie d'évitement</span></td><td>Pathologie ostéo-articulaire douloureuse</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-clinique\">marche précautionneuse</span> (ralentie, prudente, recherche d'appuis, prédominance féminine), <strong>sans déficit majeur</strong>, est très fréquente chez le sujet âgé.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 109 — Trouble marche - équilibre · 340 — <span class=\"kw-alerte\">AVC</span> · 106 — Parkinson</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":3},{"id":"131-7","rang":"A","rubrique":"Etiologies","titre":"Connaître les facteurs favorisants, les causes et facteurs de risque de chutes chez le sujet âgé","contenu":"<p>Cet objectif est le <span class=\"kw-alerte\">cœur de l'item (⭐⭐⭐⭐⭐)</span>. La chute du sujet âgé est presque toujours <strong>multifactorielle</strong> : on oppose <span class=\"kw-clinique\">les</span> facteurs <strong>prédisposants</strong> (vulnérabilité chronique) aux facteurs <strong>précipitants</strong> (événement aigu déclenchant).</p>\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">1 · Facteurs prédisposants (vulnérabilité chronique)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Âge ≥ 80 ans</span>, <span class=\"kw-clinique\">sexe féminin</span>, antécédents de <span class=\"kw-clinique\">chutes</span> et de <span class=\"kw-clinique\">fractures traumatiques</span>.</li>\n        <li><span class=\"kw-etio\">Troubles neurocognitifs</span>, symptômes de <span class=\"kw-etio\">dépression</span>, <span class=\"kw-etio\">troubles du sommeil</span>.</li>\n        <li><span class=\"kw-etio\">Dénutrition</span> protéino-énergétique ; <span class=\"kw-clinique\">faiblesse musculaire</span> des membres inférieurs.</li>\n        <li><span class=\"kw-alerte\">Polymédication (≥ 5 traitements)</span> et <span class=\"kw-alerte\">iatrogénie</span> (psychotropes, anticholinergiques, médicaments cardiovasculaires).</li>\n        <li>Pathologies donnant des troubles de la marche : <span class=\"kw-etio\">atteintes neurologiques</span> (neurovasculaire, neurodégénérative, hydrocéphalie, médullaire, parkinsonienne), <span class=\"kw-etio\">arthrose</span> des MI/rachis, anomalies des pieds, troubles proprioceptifs.</li>\n        <li>Baisse de l'<span class=\"kw-clinique\">acuité visuelle</span> et/ou du champ visuel.</li>\n      </ul>\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">2 · Facteurs précipitants (événement aigu)</h4>\n      <table >\n        <thead><tr><th>Système</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Cardiovasculaires</span></td><td>Troubles du <span class=\"kw-clinique\">rythme</span> / de la <span class=\"kw-clinique\">conduction</span> de haut degré, <span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-etio\">rétrécissement aortique serré</span>, <span class=\"kw-alerte\">hypotension orthostatique +++</span>, <span class=\"kw-clinique\">syncopes neurocardiogéniques</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Neurologiques</span></td><td><span class=\"kw-clinique\">Déficit sensitivomoteur</span> (transitoire ou constitué), <span class=\"kw-clinique\">syndrome confusionnel</span>, <span class=\"kw-clinique\">crise convulsive</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Vestibulaires</span></td><td><span class=\"kw-clinique\">Vertige</span>, <span class=\"kw-clinique\">instabilité</span>, <span class=\"kw-clinique\">nystagmus</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Infectieuses / métaboliques</span></td><td><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-bio\">hypoglycémie</span> (<span class=\"kw-etio\">iatrogène</span> ++), <span class=\"kw-bio\">hyponatrémie</span>, <span class=\"kw-bio\">hypercalcémie</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Extrinsèques</span> (environnement)</td><td>Sol mouillé/glissant, éclairage insuffisant, <span class=\"kw-clinique\">chaussage inadapté</span>, obstacles, mobilier et W.-C. inadaptés, habits trop longs.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ La recherche des <span class=\"kw-etio\">facteurs iatrogènes</span> est <strong>systématique</strong> : psychotropes (somnolence), anticholinergiques (confusion), antihypertenseurs/<span class=\"kw-ttt\">diurétiques</span> (HTO, <span class=\"kw-clinique\">déshydratation</span>), bradycardisants — <span class=\"kw-ttt\">bêtabloquant, inhibiteur calcique, digoxine</span> (<span class=\"kw-clinique\">syncope</span>). Toute introduction/modification récente dont la chronologie colle à la chute est suspecte.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":5},{"id":"131-8","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les fréquences et complications des chutes dans la population âgée","contenu":"<p>La chute du sujet âgé est un <strong>problème majeur de santé publique</strong>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Fréquence</h4>\n      <ul>\n        <li><span class=\"kw-chiffre\">1/3</span> des personnes &gt; <span class=\"kw-chiffre\">65 ans</span> et <span class=\"kw-chiffre\">1/2</span> de celles &gt; <span class=\"kw-chiffre\">85 ans</span> font au moins une chute par an.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Complications</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Complications physiques</span> (tissus mous, <span class=\"kw-clinique\">fractures osseuses</span>) et complications <span class=\"kw-clinique\">psychologiques</span>.</li>\n        <li>Augmentation de la <span class=\"kw-clinique\">dépendance</span>, des <span class=\"kw-clinique\">institutionnalisations</span> et des <span class=\"kw-clinique\">hospitalisations</span>.</li>\n        <li><span class=\"kw-alerte\">Décès à court terme</span> : environ <span class=\"kw-chiffre\">12 000 décès/an</span> en France.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":1},{"id":"131-9","rang":"A","rubrique":"Diagnostic positif","titre":"Rechercher les signes de gravité d’une chute","contenu":"<p>Devant toute chute, rechercher <strong>systématiquement</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span> pouvant imposer une prise en charge immédiate. Ils tiennent à <strong>4 éléments</strong>.</p>\n      <table >\n        <thead><tr><th>Gravité liée à…</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td>1 · Conséquences de la chute</td><td><span class=\"kw-clinique\">Traumatismes</span> (<span class=\"kw-clinique\">contusions</span>, <span class=\"kw-clinique\">plaies</span>, <span class=\"kw-clinique\">luxations</span>, <span class=\"kw-alerte\">fractures</span> — dont engrenée de l'<span class=\"kw-clinique\">ESF</span>, <span class=\"kw-imagerie\">hémorragie intracrânienne</span>) ; <span class=\"kw-clinique\">syndrome post-chute</span> ; complications de la <span class=\"kw-alerte\">station prolongée au sol</span>.</td></tr>\n          <tr><td>2 · Caractère répété</td><td><span class=\"kw-clinique\">Chutes à répétition</span> (≥ <span class=\"kw-chiffre\">2</span>/<span class=\"kw-chiffre\">12 mois</span>) ; aggravation récente de la fréquence ; &gt; <span class=\"kw-chiffre\">3</span> facteurs prédisposants ; <span class=\"kw-alerte\">station au sol &gt; 1 heure</span>.</td></tr>\n          <tr><td>3 · Étiologies</td><td>Trouble du <span class=\"kw-etio\">rythme/conduction</span>, <span class=\"kw-etio\">IDM</span>, <span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">pathologie infectieuse</span>, <span class=\"kw-bio\">hypoglycémie</span>.</td></tr>\n          <tr><td>4 · Situations médico-sociales à risque</td><td><span class=\"kw-ttt\">Anticoagulants / antiagrégants</span> ; <span class=\"kw-clinique\">isolement socio-familial</span> ; <span class=\"kw-etio\">ostéoporose avérée</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🔥 <strong>Station au sol prolongée (&gt;<span class=\"kw-chiffre\"> 1 heure</span>)</strong> = <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span> majeur (<span class=\"kw-bio\">rhabdomyolyse</span>, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-clinique\">escarres</span>, <span class=\"kw-clinique\">hypothermie</span>…).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante · 120 — Complications immobilité - décubitus · 340 — <span class=\"kw-alerte\">AVC</span></em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":4},{"id":"131-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’objectif des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","contenu":"<p>L'imagerie n'est <strong>jamais systématique</strong> mais <span class=\"kw-alerte\">orientée par la clinique</span>. Son objectif est triple : faire le <strong>bilan lésionnel, étiologique et de gravité</strong>.</p>\n      <ul>\n        <li><strong>Bilan lésionnel</strong> : rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">conséquences traumatiques</span> (<span class=\"kw-imagerie\">radiographies osseuses</span> si suspicion de fracture ; <span class=\"kw-imagerie\">TDM cérébrale</span> si traumatisme crânien).</li>\n        <li><strong>Bilan étiologique</strong> : <span class=\"kw-imagerie\">IRM cérébrale</span> ou <span class=\"kw-imagerie\">médullaire</span> à la recherche d'un <span class=\"kw-etio\">AVC</span>, d'une <span class=\"kw-etio\">compression médullaire</span>, d'une <span class=\"kw-etio\">hydrocéphalie</span>, d'une <span class=\"kw-etio\">lésion frontale</span>.</li>\n        <li><strong>Bilan de gravité</strong> : apprécier le retentissement (ex. <span class=\"kw-imagerie\">hématome sous-dural</span> chez un patient sous <span class=\"kw-ttt\">antithrombotique</span>).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span> · 120 — Complications immobilité - décubitus</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":2},{"id":"131-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan de gravité","contenu":"<p>Dans un contexte de <span class=\"kw-alerte\">chute grave</span>, <span class=\"kw-clinique\">les</span> examens à demander <strong>en <span class=\"kw-alerte\">urgence</span></strong> dépendent du contexte :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECG</span></td><td><span class=\"kw-clinique\">Malaise</span>, <span class=\"kw-clinique\">perte de connaissance</span>, FdR cardiovasculaire ou <span class=\"kw-etio\">cardiopathie</span>, suspicion d'<span class=\"kw-bio\">hyperkaliémie</span>, chute de circonstances inconnues.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographies osseuses</span></td><td>Suspicion de <span class=\"kw-clinique\">fracture</span>.</td></tr>\n          <tr><td><span class=\"kw-bio\">CPK + créatininémie</span></td><td>Séjour au sol &gt; <span class=\"kw-chiffre\">1 heure</span> (<span class=\"kw-alerte\">rhabdomyolyse</span>, <span class=\"kw-alerte\">insuffisance rénale aiguë</span>).</td></tr>\n          <tr><td><span class=\"kw-bio\">Glycémie capillaire</span></td><td>Systématique, surtout chez le diabétique sous <span class=\"kw-ttt\">insuline</span> / ADO hypoglycémiant.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Imagerie cérébrale (TDM)</span></td><td>Uniquement si <span class=\"kw-clinique\">symptôme neurologique</span> ou traumatisme crânien sous antithrombotique (<span class=\"kw-imagerie\">IRM</span> si suspicion d'<span class=\"kw-alerte\">AVC</span>).</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":3},{"id":"131-12","rang":"A","rubrique":"Diagnostic positif","titre":"Définir et décrire le syndrome post-chute","contenu":"<p>Le <span class=\"kw-def\">syndrome post-chute</span> (ou <span class=\"kw-clinique\">syndrome de désadaptation</span> psychomotrice) est une <strong>sidération des automatismes</strong> de l'équilibre et de la marche.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Rétropulsion</span> rendant la station debout impossible sans aide humaine.</li>\n        <li>Composante <span class=\"kw-clinique\">anxieuse majeure</span> déclenchée en position debout : « phobie de la marche », voire de la verticalisation.</li>\n        <li>Marche avec aide : <span class=\"kw-clinique\">petits pas glissés</span> en <span class=\"kw-clinique\">appui talonnier</span> sans déroulement du pas, retard d'initiation / <span class=\"kw-clinique\">freezing</span>.</li>\n        <li>Troubles neurologiques : <span class=\"kw-clinique\">hypertonie oppositionnelle</span>, altération des <span class=\"kw-clinique\">réactions d'adaptation posturale</span> et des <span class=\"kw-clinique\">réactions parachutes</span>.</li>\n        <li><strong>Non expliqué</strong> par <span class=\"kw-clinique\">les</span> lésions traumatiques/neurologiques de la chute, <strong>non corrélé</strong> à sa gravité ; d'autant plus marqué que le sujet est <span class=\"kw-alerte\">resté longtemps au sol</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">🔥 <strong><span class=\"kw-alerte\">Urgence</span> gériatrique</strong> à <span class=\"kw-alerte\">mauvais pronostic fonctionnel</span> : impose une <span class=\"kw-ttt\">hospitalisation</span> avec PEC pluridisciplinaire rapide (rééducation fonctionnelle, soutien psychologique). <span class=\"kw-clinique\">Évolution</span> <strong>réversible</strong> si PEC précoce ; sinon, perte d'autonomie complète.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 109 — Trouble marche - équilibre · 120 — Complications immobilité - décubitus</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":2},{"id":"131-13","rang":"B","rubrique":"Suivi/Pronostic","titre":"Décrire les conséquences médicales et psychosociales des chutes chez le sujet âgé","contenu":"<p><span class=\"kw-clinique\">Les</span> chutes engagent le <strong><span class=\"kw-def\">pronostic</span> fonctionnel et vital</strong> du sujet âgé.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Conséquences médicales</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Traumatiques</span> : <span class=\"kw-clinique\">contusions</span>, <span class=\"kw-clinique\">plaies</span>, <span class=\"kw-clinique\">luxations</span>, <span class=\"kw-alerte\">fractures</span> (<span class=\"kw-clinique\">ESF</span>, bassin), <span class=\"kw-imagerie\">hémorragies intracrâniennes</span>.</li>\n        <li>Liées à la <span class=\"kw-alerte\">station prolongée au sol</span> : <span class=\"kw-bio\">rhabdomyolyse</span>, <span class=\"kw-bio\">insuffisance rénale</span>, <span class=\"kw-bio\">hyperkaliémie</span>, <span class=\"kw-clinique\">pneumopathie d'inhalation</span>, <span class=\"kw-clinique\">hypothermie</span>, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-clinique\">escarres</span>, MTEV.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Conséquences psychosociales</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome post-chute</span>, peur de tomber, refus de la verticalisation, <span class=\"kw-clinique\">dépression</span>.</li>\n        <li>Perte d'<span class=\"kw-clinique\">autonomie</span>, augmentation de la dépendance et des <span class=\"kw-clinique\">institutionnalisations</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 120 — Complications immobilité - décubitus · 128 — Ostéopathie fragilisante</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"131-14","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les conséquences médicales urgentes d’une chute","contenu":"<p>Certaines conséquences d'une chute constituent une <span class=\"kw-alerte\">urgence médicale</span> à reconnaître d'emblée :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Fractures</span> — notamment de l'<span class=\"kw-clinique\">extrémité supérieure du fémur</span> (parfois engrenée, donc trompeuse) et <span class=\"kw-imagerie\">hémorragie intracrânienne</span> (HSD) sous antithrombotique.</li>\n        <li><span class=\"kw-bio\">Rhabdomyolyse</span> → <span class=\"kw-alerte\">insuffisance rénale aiguë</span> et <span class=\"kw-bio\">hyperkaliémie</span>, après station prolongée au sol.</li>\n        <li><span class=\"kw-clinique\">Syndrome post-chute</span> (<span class=\"kw-alerte\">urgence</span> gériatrique fonctionnelle).</li>\n        <li>Autres complications du décubitus prolongé : <span class=\"kw-clinique\">pneumopathie d'inhalation</span>, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-clinique\">hypothermie</span>, <span class=\"kw-clinique\">escarres</span>, MTEV.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 120 — Complications immobilité - décubitus · 128 — Ostéopathie fragilisante</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"131-15","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une hypotension orthostatique (HTO)","contenu":"<p>L'<span class=\"kw-def\">hypotension orthostatique (HTO)</span> est une étiologie <strong>très fréquente</strong> de chute du sujet âgé et représente un <span class=\"kw-alerte\">risque vital</span>. Définition (après quelques minutes de repos, mesurée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 minutes</span> suivant la verticalisation) :</p>\n      <ul>\n        <li>Chute de la <span class=\"kw-bio\">PA systolique ≥ <span class=\"kw-chiffre\">20 mmHg</span></span> <strong>et/ou</strong> de la <span class=\"kw-bio\">PA diastolique ≥ <span class=\"kw-chiffre\">10 mmHg</span></span> ;</li>\n        <li><strong>et/ou</strong> <span class=\"kw-bio\">PAS &lt; <span class=\"kw-chiffre\">90 mmHg</span></span> à l'orthostatisme, quelle que soit la valeur de départ.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Recherche <strong>peu sensible</strong>, à <strong>répéter</strong> (surtout le matin). Des symptômes évocateurs (<span class=\"kw-clinique\">lipothymies</span> à l'orthostatisme) malgré une recherche négative <strong>suffisent</strong> au diagnostic. Une FC qui augmente de &lt; <span class=\"kw-chiffre\">10/min</span> à l'orthostatisme doit faire évoquer un <span class=\"kw-ttt\">traitement bradycardisant</span> et/ou une <span class=\"kw-etio\">dysautonomie</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":3},{"id":"131-16","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisant l’HTO avec l’âge","contenu":"<p>L'âge favorise la survenue de l'<span class=\"kw-def\">HTO</span> par trois mécanismes :</p>\n      <ul>\n        <li>Atteinte du <span class=\"kw-clinique\">baroréflexe</span> (barorécepteurs).</li>\n        <li><span class=\"kw-clinique\">Vieillissement de la paroi artérielle</span> (rigidité).</li>\n        <li><span class=\"kw-ttt\">Réduction</span> du taux d'<span class=\"kw-bio\">aldostérone</span> et de <span class=\"kw-bio\">rénine</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":2},{"id":"131-17","rang":"A","rubrique":"Etiologie","titre":"Connaître les causes d’HTO","contenu":"<p>L'HTO du sujet âgé est souvent <strong>multifactorielle</strong>. Le bilan étiologique doit comprendre au minimum :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Iatrogénie (+++)</span>, à rechercher en priorité : dérivés <span class=\"kw-ttt\">nitrés</span>, association d'antihypertenseurs, <span class=\"kw-ttt\">alphabloquants</span>, antidépresseurs tricycliques et <span class=\"kw-ttt\">IMAO</span>, L-dopa, anticholinergiques, <span class=\"kw-ttt\">morphine</span>.</li>\n        <li><span class=\"kw-etio\">Hypovolémie / déshydratation</span> (rechercher une pathologie aiguë favorisante).</li>\n        <li><span class=\"kw-etio\">Anémie</span> (l'HTO traduit une mauvaise tolérance, pouvant justifier une transfusion).</li>\n        <li><span class=\"kw-etio\">Insuffisance cardiaque</span> (réponse hémodynamique inadaptée à l'orthostatisme).</li>\n        <li>Plus rarement <span class=\"kw-etio\">endocrinopathie</span> (<span class=\"kw-etio\">phéochromocytome</span>, <span class=\"kw-etio\">dysthyroïdie</span>, <span class=\"kw-etio\">insuffisance surrénalienne</span>).</li>\n        <li><span class=\"kw-etio\">Dysautonomie</span> : pathologies neurodégénératives (<span class=\"kw-etio\">démence à corps de Lewy</span>, <span class=\"kw-etio\">Parkinson</span>, « Parkinson + »), alitement prolongé, <span class=\"kw-etio\">neuropathie périphérique</span> (<span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">amylose</span>, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">insuffisance rénale</span>, <span class=\"kw-etio\">carences vitaminiques</span>).</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"131-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge de l’HTO","contenu":"<p>La prise en charge de l'<span class=\"kw-def\">HTO</span> est d'abord <strong>étiologique et non médicamenteuse</strong> :</p>\n      <ul>\n        <li>Éradiquer le <span class=\"kw-etio\">facteur déclenchant</span> aigu et/ou améliorer le traitement de la pathologie chronique.</li>\n        <li><strong>Revoir l'ordonnance</strong> (tous <span class=\"kw-clinique\">les</span> traitements, en priorité les hypotenseurs).</li>\n        <li>Éduquer le patient à <span class=\"kw-ttt\">décomposer son passage en orthostatisme</span>.</li>\n        <li><span class=\"kw-ttt\">Contention veineuse de classe 2</span> ; <span class=\"kw-ttt\">hydratation</span> correcte.</li>\n      </ul>\n      <p>En <strong>2ᵉ intention</strong> : discuter la <span class=\"kw-ttt\">midodrine</span> (vasoconstricteur) ou la <span class=\"kw-ttt\">fludrocortisone</span> (inflation hémodynamique, <span class=\"kw-ci\">hors AMM</span>), en respectant <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">contre-indications</span>.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":1},{"id":"131-19","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","contenu":"<p>L'imagerie n'est <strong>pas un examen systématique</strong> du bilan de chute : son indication est posée par la <span class=\"kw-alerte\">clinique</span>.</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">TDM cérébrale en urgence</span> : uniquement si <span class=\"kw-clinique\">symptôme neurologique</span>, ou <span class=\"kw-clinique\">traumatisme crânien sous antithrombotique</span> (<span class=\"kw-ttt\">anticoagulant</span>/antiplaquettaire).</li>\n        <li><span class=\"kw-imagerie\">IRM cérébrale en 1ʳᵉ intention</span> : suspicion d'<span class=\"kw-etio\">AVC</span> (dans le délai de <span class=\"kw-ttt\">thrombolyse</span> / thrombectomie).</li>\n        <li><span class=\"kw-imagerie\">Radiographies osseuses</span> : suspicion de <span class=\"kw-clinique\">fracture</span>.</li>\n        <li><span class=\"kw-imagerie\">IRM médullaire</span> : suspicion de <span class=\"kw-etio\">compression médullaire</span> / myélopathie.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ L'imagerie cérébrale ne fait <strong>pas</strong> partie des examens systématiques d'un bilan de chute (cf. objectif « autres examens complémentaires »).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span></em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":1},{"id":"131-20","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir énoncer les autres examens complémentaires chez un patient âgé venant de faire une chute","contenu":"<p>En dehors de l'<span class=\"kw-alerte\">urgence</span> et de l'imagerie, le bilan étiologique d'une chute comporte (selon l'orientation clinique) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">ECG standard 12 dérivations</span> — fait partie de l'examen clinique.</li>\n        <li>Dosage de la <span class=\"kw-bio\">vitamine D (25(OH)-D)</span> — évaluation du risque fracturaire.</li>\n        <li>Bilan <span class=\"kw-ttt\">biologique</span> « de routine » facile : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">NFS</span> (anémie), <span class=\"kw-bio\">créatininémie</span>, recherche de <span class=\"kw-clinique\">déshydratation</span> et de troubles hydroélectrolytiques.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Examens <strong>NON systématiques</strong> (uniquement si orientation clinique/<span class=\"kw-imagerie\">ECG</span>) : <span class=\"kw-bio\">HbA1c</span>, <span class=\"kw-imagerie\">EEG</span>, imagerie cérébrale, <span class=\"kw-imagerie\">écho-doppler</span> des troncs supra-aortiques, <span class=\"kw-imagerie\">Holter-ECG</span>, <span class=\"kw-imagerie\">échographie cardiaque</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":5},{"id":"131-21","rang":"A","rubrique":"Prise en charge","titre":"Savoir proposer une attitude thérapeutique au décours d’une chute (HAS) et les mesures de prévention de récidive","contenu":"<p>L'objectif du <strong>plan de soins</strong> est d'<span class=\"kw-alerte\">éviter ou diminuer le risque de récidive</span> de chutes. Démarche structurée (HAS) :</p>\n      <ul>\n        <li>Prendre en charge l'<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-clinique\">conséquences traumatiques</span>, facteur précipitant aigu).</li>\n        <li>Corriger le(s) <span class=\"kw-etio\">facteur(s) précipitant(s)</span>, intrinsèques et extrinsèques.</li>\n        <li>Prendre en charge la composante <strong>améliorable</strong> des <span class=\"kw-etio\">facteurs prédisposants</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mesures systématiques de prévention de récidive</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Révision de l'ensemble des médicaments</span> (allègement des traitements à risque).</li>\n        <li><span class=\"kw-ttt\">Chaussures fermées</span> à talons larges et bas (<span class=\"kw-chiffre\">2-3 cm</span>), semelles fines et fermes, t<span class=\"kw-chiffre\">ige</span> remontant haut (stimulation proprioceptive).</li>\n        <li><span class=\"kw-ttt\">Activité physique</span> régulière (marche ≥ <span class=\"kw-chiffre\">30 min/jour</span>) ; <span class=\"kw-ttt\">aide technique à la marche</span> si nécessaire.</li>\n        <li>Correction d'une carence en <span class=\"kw-bio\">vitamine D</span>, recherche et PEC d'une <span class=\"kw-etio\">ostéoporose</span> et d'une <span class=\"kw-etio\">dénutrition</span>.</li>\n        <li>Évaluation du <span class=\"kw-clinique\">domicile</span> (famille / ergothérapeute) ; <span class=\"kw-ttt\">kinésithérapie</span> motrice.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante · 120 — Complications immobilité - décubitus</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":4},{"id":"131-22","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de kinésithérapie type pour un sujet âgé chuteur","contenu":"<p>L'<span class=\"kw-ttt\">ordonnance type de kinésithérapie</span> post-chute (souvent à domicile initialement, <strong>plurihebdomadaire</strong>, à poursuivre en auto-rééducation entre <span class=\"kw-clinique\">les</span> séances) comporte :</p>\n      <ul>\n        <li>Rééducation de la <span class=\"kw-clinique\">marche</span> (éventuellement avec aide technique : déambulateur, canne).</li>\n        <li><span class=\"kw-clinique\">Musculation proximale</span> des membres inférieurs et du rachis.</li>\n        <li>Travail de l'<span class=\"kw-clinique\">équilibre</span>.</li>\n        <li>Travail des <span class=\"kw-clinique\">transferts</span> (lit – fauteuil – toilettes).</li>\n        <li>Travail du <span class=\"kw-clinique\">relever du sol</span> en cas de chute.</li>\n      </ul>\n      <div class=\"callout callout-warn\">💡 Mention « <strong>SOINS URGENTS</strong> » sur l'ordonnance pour ne pas attendre l'entente préalable de la CPAM.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/troubles-de-la-marche-et-de-lequilibre-troubles-de-la-marche-et-de-lequilibre-chez-le-sujet-age","label":"Collège CEN — Troubles marche & équilibre du sujet âgé"},{"href":"https://www.youtube.com/watch?v=ncrZ5G-8z5Q&t=3s","label":"YouTube — Physiologie de la marche"}],"cards":[{"i":"00369ad1012e","n":131,"o":"131-10","u":"Examens complémentaires","t":"Connaître l’objectif des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Dans le cadre d'un bilan lésionnel, quelles sont les situations où des examens d'imagerie sont indiqués pour un trouble de la marche ou de l'équilibre chez le sujet âgé ?","a":"<p>Devant une suspicion de <strong>conséquences traumatiques</strong> :</p><ul><li>Des <strong>radiographies osseuses</strong> sont indiquées en cas de suspicion de fracture.</li><li>Un <strong>TDM cérébral</strong> est indiqué en cas de traumatisme crânien.</p></li></ul>"},{"i":"3386b8048490","n":131,"o":"131-10","u":"Examens complémentaires","t":"Connaître l’objectif des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Comment l'imagerie contribue-t-elle au bilan de gravité dans les troubles de la marche et de l'équilibre du sujet âgé ?","a":"<p>L'imagerie permet d'apprécier le <strong>retentissement</strong> des troubles, par exemple en détectant un <strong>hématome sous-dural</strong> chez un patient sous <strong>antithrombotique</strong>.</p>"},{"i":"8a871c8e6cd1","n":131,"o":"131-10","u":"Examens complémentaires","t":"Connaître l’objectif des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Quel est l'objectif global de la réalisation d'examens d'imagerie devant un trouble de la marche ou de l'équilibre du sujet âgé ?","a":"<p>L'objectif de l'imagerie est <strong>triple</strong> :</p><ul><li>Faire un <strong>bilan lésionnel</strong>.</li><li>Faire un <strong>bilan étiologique</strong>.</li><li>Faire un <strong>bilan de gravité</strong>.</li></ul>"},{"i":"cc5d4c447ede","n":131,"o":"131-10","u":"Examens complémentaires","t":"Connaître l’objectif des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Quelles étiologies justifient la réalisation d'une IRM cérébrale ou médullaire dans le bilan étiologique d'un trouble de la marche ou de l'équilibre chez le sujet âgé ?","a":"<p>Une IRM cérébrale ou médullaire est indiquée pour rechercher :</p><ul><li>Un <strong>AVC</strong> (accident vasculaire cérébral).</li><li>Une <strong>compression médullaire</strong>.</li><li>Une <strong>hydrocéphalie</strong>.</li><li>Une <strong>lésion frontale</strong>.</li></ul>"},{"i":"2d74e6603c8b","n":131,"o":"131-11","u":"Examens complémentaires","t":"Connaître le bilan de gravité","q":"Dans quel contexte de chute grave chez le sujet âgé l'ECG est-il un examen d'urgence indiqué ?","a":"<p>L'ECG est indiqué en urgence en cas de <ul><li><strong>malaise</strong></li><li><strong>perte de connaissance</strong></li><li><strong>facteur de risque cardiovasculaire</strong> ou <strong>cardiopathie connue</strong></li><li>suspicion d'<strong>hyperkaliémie</strong></li><li>chute de <strong>circonstances inconnues</strong>.</li></ul></p>"},{"i":"468fad90c49e","n":131,"o":"131-11","u":"Examens complémentaires","t":"Connaître le bilan de gravité","q":"Pourquoi doit-on doser les CPK et la créatininémie en urgence chez un sujet âgé après une chute, et dans quel contexte ?","a":"<p>Ces dosages sont indiqués si le <strong>séjour au sol a excédé une heure</strong>, afin de rechercher une <strong>rhabdomyolyse</strong> ou une <strong>insuffisance rénale aiguë</strong>.</p>"},{"i":"9147b64ee57c","n":131,"o":"131-11","u":"Examens complémentaires","t":"Connaître le bilan de gravité","q":"Quand l'imagerie cérébrale est-elle indiquée en urgence après une chute chez le sujet âgé ?","a":"<p>L'imagerie cérébrale (<strong>TDM</strong>) est indiquée uniquement en cas de <strong>symptôme neurologique</strong> ou de <strong>traumatisme crânien sous traitement antithrombotique</strong>. Une <strong>IRM</strong> est à privilégier en cas de <strong>suspicion d'AVC</strong>.</p>"},{"i":"c5386b776f5d","n":131,"o":"131-11","u":"Examens complémentaires","t":"Connaître le bilan de gravité","q":"Quand faudrait-il demander des radiographies osseuses en urgence chez un sujet âgé après une chute ?","a":"<p>Des radiographies osseuses sont indiquées en urgence uniquement en cas de <strong>suspicion de fracture</strong>.</p>"},{"i":"30b80fac7d78","n":131,"o":"131-12","u":"Diagnostic positif","t":"Définir et décrire le syndrome post-chute","q":"Définition du syndrome post-chute chez le sujet âgé ?","a":"<p>Le syndrome post-chute, ou <strong>syndrome de désadaptation psychomotrice</strong>, se caractérise par une <strong>sidération des automatismes de l'équilibre et de la marche</strong> survenant après une chute, et ce, sans être expliqué par les lésions traumatiques ou neurologiques directes de la chute.</p>"},{"i":"33fceedca8f9","n":131,"o":"131-12","u":"Diagnostic positif","t":"Définir et décrire le syndrome post-chute","q":"Quelle est la prise en charge et le pronostic du syndrome post-chute ?","a":"<p>C'est une <strong>urgence gériatrique</strong> à mauvais pronostic fonctionnel si non traitée. Elle impose une <strong>hospitalisation</strong> avec une <strong>prise en charge pluridisciplinaire rapide</strong> incluant rééducation fonctionnelle et soutien psychologique. Son évolution est <strong>réversible si la prise en charge est précoce</strong>, mais peut entraîner une perte d'autonomie complète dans le cas contraire. L'intensité des symptômes est d'autant plus marquée que le sujet est resté longtemps au sol après la chute.</p>"},{"i":"f83cc9bd95f7","n":131,"o":"131-12","u":"Diagnostic positif","t":"Définir et décrire le syndrome post-chute","q":"Quels sont les signes cliniques majeurs du syndrome post-chute ?","a":"<ul><li>Une <strong>rétropulsion</strong> rendant la station debout impossible sans aide humaine.</li><li>Une <strong>composante anxieuse majeure</strong> (phobie de la marche, de la verticalisation).</li><li>Des troubles de la marche : <strong>petits pas glissés en appui talonnier sans déroulement du pas</strong>, retard d'initiation ou <strong>freezing</strong>.</li><li>Des troubles neurologiques : <strong>hypertonie oppositionnelle</strong>, altération des réactions d'adaptation posturale et des réactions parachutes.</li></ul>"},{"i":"2c0f0ffaba69","n":131,"o":"131-14","u":"Identifier une urgence","t":"Connaître les conséquences médicales urgentes d’une chute","q":"Quelles sont les complications générales du décubitus prolongé (après une chute) chez le sujet âgé ?","a":"<ul><li>La <strong>pneumopathie d'inhalation</strong>.</li><li>La <strong>déshydratation</strong>.</li><li>L'<strong>hypothermie</strong>.</li><li>Les <strong>escarres</strong>.</li><li>La <strong>maladie thrombo-embolique veineuse (MTEV)</strong>.</li></ul>"},{"i":"34427c54d89e","n":131,"o":"131-14","u":"Identifier une urgence","t":"Connaître les conséquences médicales urgentes d’une chute","q":"Quelle complication neurologique grave doit être systématiquement recherchée après une chute chez un sujet âgé sous antithrombotiques ?","a":"<p>Il faut systématiquement rechercher une <strong>hémorragie intracrânienne</strong> (notamment un <strong>hématome sous-dural - HSD</strong>), surtout si le patient est sous traitement <strong>anti-thrombotique</strong>.</p>"},{"i":"41f907aaf5c6","n":131,"o":"131-14","u":"Identifier une urgence","t":"Connaître les conséquences médicales urgentes d’une chute","q":"Quelles sont les complications immédiates de la station prolongée au sol (après une chute) chez le sujet âgé ?","a":"<ul><li>Une <strong>rhabdomyolyse</strong>, pouvant entraîner une <strong>insuffisance rénale aiguë</strong> et une <strong>hyperkaliémie</strong>.</li><li>Un <strong>syndrome post-chute</strong> (urgence gériatrique fonctionnelle).</li></ul>"},{"i":"ebcdab0f424c","n":131,"o":"131-14","u":"Identifier une urgence","t":"Connaître les conséquences médicales urgentes d’une chute","q":"Quelles sont les fractures urgentes à rechercher après une chute chez le sujet âgé ?","a":"<p>La fracture la plus importante à rechercher est celle de l'<strong>extrémité supérieure du fémur</strong>. Il faut être particulièrement vigilant car elle peut être engrenée et <strong>trompeuse</strong>, masquant parfois sa gravité initiale.</p>"},{"i":"a06b85f30343","n":131,"o":"131-15","u":"Définition","t":"Connaître la définition d’une hypotension orthostatique (HTO)","q":"Quelle est la valeur d'augmentation de la fréquence cardiaque à l'orthostatisme qui doit faire évoquer un traitement bradycardisant et/ou une dysautonomie en cas de suspicion d'hypotension orthostatique ?","a":"<p>Une <strong>augmentation de la fréquence cardiaque &lt; 10/min</strong> à l'orthostatisme doit faire évoquer un traitement bradycardisant et/ou une dysautonomie.</p>"},{"i":"a67839ff4e7f","n":131,"o":"131-15","u":"Définition","t":"Connaître la définition d’une hypotension orthostatique (HTO)","q":"Quelle est la définition chiffrée d'une hypotension orthostatique chez le sujet âgé, selon les critères de pression artérielle, suite à une verticalisation ?","a":"<p>L'hypotension orthostatique est définie par :</p><ul><li>Une chute de la <strong>Pression Artérielle Systolique (PAS) ≥ 20 mmHg</strong>.</li><li><u>Et/ou</u> une chute de la <strong>Pression Artérielle Diastolique (PAD) ≥ 10 mmHg</strong>.</li><li><u>Et/ou</u> une <strong>PAS &lt; 90 mmHg</strong> à l'orthostatisme, quelle que soit la valeur de départ.</li></ul><p>Ces mesures sont effectuées dans les <strong>5 minutes suivant la verticalisation</strong>, après quelques minutes de repos en position allongée.</p>"},{"i":"dc4f043e54d4","n":131,"o":"131-15","u":"Définition","t":"Connaître la définition d’une hypotension orthostatique (HTO)","q":"Au-delà des critères chiffrés de pression artérielle, quelle est la démarche diagnostique si la recherche d'une hypotension orthostatique initiale est négative mais que des symptômes sont présents ?","a":"<p>Si la recherche initiale est négative mais que des symptômes évocateurs, tels que des <strong>lipothymies à l'orthostatisme</strong>, sont présents, ces symptômes <strong>suffisent au diagnostic</strong>. La mesure de l'hypotension orthostatique est considérée comme peu sensible et peut nécessiter d'être répétée, notamment le matin.</p>"},{"i":"24b7c6d1e758","n":131,"o":"131-17","u":"Etiologie","t":"Connaître les causes d’HTO","q":"Quelle est la principale cause d'hypotension orthostatique (HTO) chez le sujet âgé selon le contenu fourni ?","a":"<p>La principale cause, à rechercher en priorité, est l'<strong>iatrogénie</strong>.</p>"},{"i":"34b310b50b44","n":131,"o":"131-17","u":"Etiologie","t":"Connaître les causes d’HTO","q":"Quels sont les exemples de médicaments pouvant iatrogéniquement provoquer une HTO chez le sujet âgé ?","a":"<ul><li>Les <strong>dérivés nitrés</strong></li><li>L'association d'<strong>antihypertenseurs</strong></li><li>Les <strong>alphabloquants</strong></li><li>Les <strong>antidépresseurs tricycliques et IMAO</strong></li><li>La <strong>L-dopa</strong></li><li>Les <strong>anticholinergiques</strong></li><li>La <strong>morphine</strong></li></ul>"},{"i":"4afe6c5ad6ee","n":131,"o":"131-17","u":"Etiologie","t":"Connaître les causes d’HTO","q":"Quelles sont les causes plus rares d'HTO chez le sujet âgé liées à une dysautonomie ou des endocrinopathies ?","a":"<ul><li><strong>Dysautonomie</strong> sur :<ul><li>Pathologies neurodégénératives (<strong>démence à corps de Lewy, Parkinson, « Parkinson + »</strong>)</li><li><strong>Alitement prolongé</strong></li><li><strong>Neuropathie périphérique</strong> (ex: diabète, amylose, alcool, insuffisance rénale, carences vitaminiques)</li></ul></li><li><strong>Endocrinopathies</strong> :<ul><li><strong>Phéochromocytome</strong></li><li><strong>Dysthyroïdie</strong></li><li><strong>Insuffisance surrénalienne</strong></li></ul></li></ul>"},{"i":"bfba1861768a","n":131,"o":"131-17","u":"Etiologie","t":"Connaître les causes d’HTO","q":"Quelles sont les causes non médicamenteuses les plus fréquentes d'HTO chez le sujet âgé mentionnées dans le contenu ?","a":"<ul><li>L'<strong>hypovolémie/déshydratation</strong> (rechercher une pathologie aiguë favorisante)</li><li>L'<strong>anémie</strong> (traduisant une mauvaise tolérance)</li><li>L'<strong>insuffisance cardiaque</strong> (réponse hémodynamique inadaptée à l'orthostatisme)</li></ul>"},{"i":"109ab498e57d","n":131,"o":"131-18","u":"Prise en charge","t":"Connaître la prise en charge de l’HTO","q":"Quels sont les traitements médicamenteux de deuxième intention qui peuvent être discutés dans la prise en charge de l'hypotension orthostatique (HTO) et leurs mécanismes d'action ?","a":"<p>En deuxième intention, on peut discuter :</p><ul><li>La <strong>midodrine</strong>, qui est un <strong>vasoconstricteur</strong>.</li><li>La <strong>fludrocortisone</strong>, qui agit par <strong>inflation hémodynamique</strong> (à noter qu'elle est utilisée hors AMM dans cette indication).</li></ul><p>Il est impératif de respecter leurs contre-indications.</p>"},{"i":"607e6602250d","n":131,"o":"131-18","u":"Prise en charge","t":"Connaître la prise en charge de l’HTO","q":"Quelles sont les mesures non médicamenteuses de première intention dans la prise en charge de l'hypotension orthostatique (HTO) ?","a":"<ul><li>Éradiquer le <strong>facteur déclenchant aigu</strong> et/ou améliorer le traitement de la <strong>pathologie chronique</strong>.</li><li>Revoir l'<strong>ordonnance</strong>, en priorisant les <strong>hypotenseurs</strong>.</li><li>Éduquer le patient à <strong>décomposer son passage en orthostatisme</strong>.</li><li>Prescrire une <strong>contention veineuse de classe 2</strong>.</li><li>Assurer une <strong>hydratation correcte</strong>.</li></ul>"},{"i":"e771874471f8","n":131,"o":"131-18","u":"Prise en charge","t":"Connaître la prise en charge de l’HTO","q":"Quelle est la double approche initiale de la prise en charge de l'hypotension orthostatique (HTO) chez le sujet âgé ?","a":"<p>La prise en charge initiale de l'HTO est d'abord <strong>étiologique</strong> et <strong>non médicamenteuse</strong>.</p>"},{"i":"2fc4e576a9ee","n":131,"o":"131-19","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Quelle est l'indication générale des examens d'imagerie dans le bilan d'un trouble de la marche ou de l'équilibre chez le sujet âgé ?","a":"<p>L'imagerie n'est <strong>pas systématique</strong> dans le bilan d'un trouble de la marche ou de l'équilibre du sujet âgé. Son indication est posée par la <strong>clinique</strong>.</p>"},{"i":"45dd5e288f54","n":131,"o":"131-19","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Quand des radiographies osseuses ou une IRM médullaire sont-elles indiquées en cas de trouble de la marche ou de l'équilibre récents chez le sujet âgé ?","a":"<ul><li>Des <strong>radiographies osseuses</strong> sont indiquées en cas de <strong>suspicion de fracture</strong>.</li><li>Une <strong>IRM médullaire</strong> est indiquée en cas de <strong>suspicion de compression médullaire</strong> ou de <strong>myélopathie</strong>.</li></ul>"},{"i":"868d1624452b","n":131,"o":"131-19","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Quand une IRM cérébrale en première intention est-elle indiquée face à un trouble de la marche ou de l'équilibre du sujet âgé ?","a":"<p>Une IRM cérébrale est indiquée en première intention en cas de <strong>suspicion d'AVC</strong> (notamment si le patient est dans le délai de thrombolyse ou thrombectomie).</p>"},{"i":"ce0e988608c0","n":131,"o":"131-19","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant un trouble de la marche ou de l’équilibre du sujet âgé","q":"Dans quelles situations spécifiques une TDM cérébrale en urgence est-elle indiquée en cas de trouble de la marche ou de l'équilibre chez le sujet âgé ?","a":"<p>Une TDM cérébrale en urgence est indiquée uniquement si il existe :</p><ul><li>Un <strong>symptôme neurologique</strong></li><li>Un <strong>traumatisme crânien sous antithrombotique</strong> (anticoagulant ou antiplaquettaire)</li></ul>"},{"i":"504c0c7e3884","n":131,"o":"131-21","u":"Prise en charge","t":"Savoir proposer une attitude thérapeutique au décours d’une chute (HAS) et les mesures de prévention de récidive","q":"Quelles sont les caractéristiques recommandées pour les chaussures du sujet âgé afin de prévenir les chutes ?","a":"<p>Pour prévenir les chutes, les chaussures du sujet âgé doivent être <strong>fermées</strong>, avec des <strong>talons larges et bas</strong> (idéalement <strong>2-3 cm</strong>), des <strong>semelles fines et fermes</strong>, et une <strong>tige remontant haut</strong> pour améliorer la stimulation proprioceptive.</p>"},{"i":"a456967efc70","n":131,"o":"131-21","u":"Prise en charge","t":"Savoir proposer une attitude thérapeutique au décours d’une chute (HAS) et les mesures de prévention de récidive","q":"Quelles sont les mesures systématiques de prévention de récidive de chutes à mettre en place chez le sujet âgé ?","a":"<p>Les mesures systématiques de prévention de récidive de chutes incluent :</p><ul><li>Une <strong>révision de l'ensemble des médicaments</strong>, avec un allègement des traitements à risque.</li><li>Le port de <strong>chaussures fermées à talons larges et bas</strong> (2-3 cm), avec des semelles fines et fermes et une tige remontant haut.</li><li>Une <strong>activité physique régulière</strong> (marche ≥ 30 min/jour), avec une aide technique à la marche si nécessaire.</li><li>La <strong>correction d'une carence en vitamine D</strong>, la recherche et la PEC d'une ostéoporose et d'une dénutrition.</li><li>Une <strong>évaluation du domicile</strong> (par la famille ou un ergothérapeute).</li><li>Une <strong>kinésithérapie motrice</strong>.</li></ul>"},{"i":"b6ac61e3d6dc","n":131,"o":"131-21","u":"Prise en charge","t":"Savoir proposer une attitude thérapeutique au décours d’une chute (HAS) et les mesures de prévention de récidive","q":"Quelle est l'attitude thérapeutique structurée à adopter au décours d'une chute chez le sujet âgé selon la HAS ?","a":"<p>L'attitude thérapeutique au décours d'une chute chez le sujet âgé, selon la HAS, comprend plusieurs étapes :</p><ul><li>Prendre en charge l'<strong>urgence</strong> (conséquences traumatiques, facteur précipitant aigu).</li><li><strong>Corriger le(s) facteur(s) précipitant(s)</strong>, qu'ils soient intrinsèques ou extrinsèques.</li><li>Prendre en charge la <strong>composante améliorable des facteurs prédisposants</strong>.</li></ul>"},{"i":"18d04e444303","n":131,"o":"131-4","u":"Diagnostic positif","t":"Connaître les troubles de la marche (voir aussi item 109)","q":"Comment identifier une ataxie proprioceptive chez un sujet âgé ?","a":"<p>L'ataxie proprioceptive est caractérisée par une station debout et une marche talonnante, aggravées à l'<strong>occlusion des yeux (signe de Romberg aggravé)</strong>, ce qui la distingue des autres ataxies.</p>"},{"i":"21fb9d1da163","n":131,"o":"131-4","u":"Diagnostic positif","t":"Connaître les troubles de la marche (voir aussi item 109)","q":"Quelles sont les principales étiologies des troubles de la marche hyperkinétiques chez le sujet âgé ?","a":"<p>Les troubles de la marche hyperkinétiques du sujet âgé peuvent être causés par :</p><ul><li>La <strong>dystonie</strong> (la plus fréquente).</li><li>La <strong>chorée</strong>.</li><li>Les <strong>tremblements</strong>.</li></ul>"},{"i":"40f8c8afc10c","n":131,"o":"131-4","u":"Diagnostic positif","t":"Connaître les troubles de la marche (voir aussi item 109)","q":"Quelles sont les caractéristiques d'une ataxie vestibulaire et d'une ataxie cérébelleuse dans les troubles de la marche du sujet âgé ?","a":"<ul><li>L'<strong>ataxie vestibulaire</strong> se manifeste par une marche <strong>latéralisée</strong> avec une déviation, reproduisant une marche \"en étoile\" en l'absence de repères visuels (marche aveugle).</li><li>L'<strong>ataxie cérébelleuse</strong> se caractérise par une base de sustentation <strong>élargie</strong> (polygone de sustentation élargi) et n'est <strong>pas aggravée par l'occlusion des yeux</strong>.</li></ul>"},{"i":"854ef02a0fe6","n":131,"o":"131-4","u":"Diagnostic positif","t":"Connaître les troubles de la marche (voir aussi item 109)","q":"Quels sont les différents troubles de la marche dits déficitaires chez le sujet âgé ?","a":"<ul><li>Le <strong>steppage</strong>, dû à un déficit des muscles releveurs du pied.</li><li>Le <strong>fauchage</strong>, typique du syndrome pyramidal.</li><li>La <strong>boiterie de Trendelenburg</strong>, liée à une faiblesse des muscles fessiers.</li><li>La <strong>marche dandinante</strong>.</li></ul>"},{"i":"98841c7eb421","n":131,"o":"131-4","u":"Diagnostic positif","t":"Connaître les troubles de la marche (voir aussi item 109)","q":"Quelles sont les causes fréquentes de marche hypokinétique chez le sujet âgé ?","a":"<p>La marche hypokinétique est une <strong>marche à petits pas</strong>. Les causes les plus fréquentes comprennent les <strong>syndromes parkinsoniens</strong>, l'<strong>hydrocéphalie chronique de l'adulte</strong> et les <strong>états lacunaires</strong>.</p>"},{"i":"9d11849e8538","n":131,"o":"131-5","u":"Définition","t":"Connaître la définition d’une chute et d’une chute à répétition (HAS)","q":"Selon l'HAS, comment se définit une chute à répétition chez la personne âgée ?","a":"<p>Une chute à répétition est définie par la survenue d'<strong>au moins deux chutes</strong> sur une période de <strong>douze mois</strong>.</p>"},{"i":"fa7594ed5f4d","n":131,"o":"131-5","u":"Définition","t":"Connaître la définition d’une chute et d’une chute à répétition (HAS)","q":"Selon l'HAS, quelle est la définition d'une chute chez la personne âgée ?","a":"<p>La chute est définie comme le fait de se retrouver involontairement sur le sol ou dans une position de niveau inférieur par rapport à la position de départ.</p>"},{"i":"2a4d0f4ffc9d","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Quelles sont les principales causes d'une marche apraxique ou d'une astasie-abasie chez le sujet âgé ?","a":"<p>Les principales causes incluent une atteinte <strong>frontale</strong>, une <strong>hydrocéphalie à pression normale</strong> ou un <strong>état lacunaire</strong>.</p>"},{"i":"2ca84f79c56f","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Quelles sont les caractéristiques de la marche parkinsonienne ?","a":"<p>La marche parkinsonienne se caractérise par des <strong>petits pas</strong>, une <strong>perte du ballant des bras</strong>, un <strong>freezing</strong> (blocage transitoire) et une <strong>festination</strong> (accélération involontaire des pas).</p>"},{"i":"7b590ceb3d29","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Dans quel contexte clinique la marche ataxique pseudo-ébrieuse est-elle observée chez le sujet âgé ?","a":"<p>La marche ataxique pseudo-ébrieuse évoque une atteinte <strong>cérébelleuse</strong>.</p>"},{"i":"7e89c613bd34","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Comment doit être réalisée systématiquement l'évaluation de la marche chez le sujet âgé ?","a":"<p>L'examen doit être réalisé <strong>nu-pieds</strong>, en faisant marcher le patient <strong>en ligne droite</strong>, et en observant le <strong>demi-tour</strong>.</p>"},{"i":"c2e5c8389d8a","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Décrivez les caractéristiques de la marche précautionneuse chez le sujet âgé.","a":"<p>La marche précautionneuse est une marche <strong>ralentie</strong> et <strong>prudente</strong>, avec une recherche fréquente d'<strong>appuis</strong>. Elle est très fréquente, prédomine chez la femme, et ne s'accompagne pas de déficit moteur majeur.</p>"},{"i":"e7ebcc5d60ea","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Quelle est l'origine la plus fréquente d'une marche spastique en ciseaux chez le sujet âgé ?","a":"<p>La marche spastique en ciseaux est caractéristique d'une atteinte <strong>pyramidale bilatérale</strong>.</p>"},{"i":"ef9b676efbc7","n":131,"o":"131-6","u":"Diagnostic positif","t":"Connaître les principaux troubles de la marche et de l’équilibre chez le sujet âgé","q":"Quand observe-t-on une marche en steppage et quelle est sa signification ?","a":"<p>La marche en steppage est la conséquence d'une atteinte de la <strong>loge antéro-externe de la jambe</strong> (correspondant à une atteinte radiale <strong>L4-L5</strong> ou du <strong>nerf fibulaire commun</strong>).</p>"},{"i":"0e59b09d2186","n":131,"o":"131-7","u":"Etiologies","t":"Connaître les facteurs favorisants, les causes et facteurs de risque de chutes chez le sujet âgé","q":"Quelles sont les causes neurologiques et vestibulaires précipitant la chute chez le sujet âgé ?","a":"<p>Les causes neurologiques précipitant la chute chez le sujet âgé sont :</p><ul><li>Un <strong>déficit sensitivomoteur</strong> (transitoire ou constitué).</li><li>Un <strong>syndrome confusionnel</strong>.</li><li>Une crise convulsive.</li></ul><p>Les causes vestibulaires comprennent :</p><ul><li>Le <strong>vertige</strong>.</li><li>L'instabilité.</li><li>Le <strong>nystagmus</strong>.</li></ul>"},{"i":"5f7881b29384","n":131,"o":"131-7","u":"Etiologies","t":"Connaître les facteurs favorisants, les causes et facteurs de risque de chutes chez le sujet âgé","q":"Quelles sont les principales causes cardiovasculaires précipitant la chute chez le sujet âgé ?","a":"<p>Les principales causes cardiovasculaires précipitant la chute chez le sujet âgé sont :</p><ul><li>Les <strong>troubles du rythme ou de la conduction</strong> de haut degré.</li><li>Un <strong>syndrome coronarien aigu (SCA)</strong>, une embolie pulmonaire ou un rétrécissement aortique serré.</li><li>L'<strong>hypotension orthostatique</strong>.</li><li>Les syncopes neurocardiogéniques.</li></ul>"},{"i":"a6c5c8406475","n":131,"o":"131-7","u":"Etiologies","t":"Connaître les facteurs favorisants, les causes et facteurs de risque de chutes chez le sujet âgé","q":"Quels sont les facteurs environnementaux et les causes iatrogènes à rechercher systématiquement en cas de chute du sujet âgé ?","a":"<p>Les facteurs environnementaux précipitant la chute sont souvent liés à :</p><ul><li>Un <strong>sol mouillé/glissant</strong>.</li><li>Un <strong>éclairage insuffisant</strong>.</li><li>Un <strong>chaussage inadapté</strong>.</li><li>La présence d'obstacles, un mobilier ou des WC inadaptés.</li><li>Des habits trop longs.</li></ul><p>La recherche de facteurs iatrogènes est systématique :</p><ul><li>Les <strong>psychotropes</strong> (causant somnolence).</li><li>Les <strong>anticholinergiques</strong> (entraînant confusion).</li><li>Les <strong>antihypertenseurs ou diurétiques</strong> (provoquant hypotension orthostatique, déshydratation).</li><li>Les <strong>bradycardisants</strong> (bêtabloquants, inhibiteurs calciques, digoxine) pouvant causer des syncopes.</li></ul><p>Toute introduction ou modification récente de traitement dont la chronologie concorde avec la chute est suspecte.</p>"},{"i":"acf2c6b0aa88","n":131,"o":"131-7","u":"Etiologies","t":"Connaître les facteurs favorisants, les causes et facteurs de risque de chutes chez le sujet âgé","q":"Quels sont les facteurs prédisposants (vulnérabilité chronique) aux chutes chez le sujet âgé ?","a":"<p>Les facteurs prédisposants aux chutes chez le sujet âgé incluent :</p><ul><li>Un âge <strong>supérieur ou égal à 80 ans</strong> et le <strong>sexe féminin</strong>.</li><li>Des antécédents de <strong>chutes et de fractures traumatiques</strong>.</li><li>Les <strong>troubles neurocognitifs</strong>, symptômes de dépression et troubles du sommeil.</li><li>La <strong>dénutrition protéino-énergétique</strong> et la faiblesse musculaire des membres inférieurs.</li><li>La <strong>polymédication</strong> (≥ 5 traitements) et l'iatrogénie (psychotropes, anticholinergiques, médicaments cardiovasculaires).</li><li>Des pathologies entraînant des troubles de la marche : atteintes neurologiques (neurovasculaire, neurodégénérative, hydrocéphalie, médullaire, parkinsonienne), <strong>arthrose</strong> des membres inférieurs/rachis, anomalies des pieds, troubles proprioceptifs.</li><li>Une baisse de l'<strong>acuité visuelle</strong> et/ou du champ visuel.</li></ul>"},{"i":"9c4de789b986","n":131,"o":"131-9","u":"Diagnostic positif","t":"Rechercher les signes de gravité d’une chute","q":"Quels sont les signes de gravité d'une chute chez le sujet âgé, liés à son caractère répété ou à la situation de la chute ?","a":"<p>Les signes de gravité incluent :</p><ul><li>Les <strong>chutes à répétition</strong> (définies par <strong>plus de 2 chutes par an</strong>).</li><li>L'<strong>aggravation récente de la fréquence des chutes</strong>.</li><li>La présence de <strong>plus de 3 facteurs prédisposants</strong>.</li><li>Une <strong>station au sol prolongée de plus d'une heure</strong>, qui est un critère de gravité majeur.</p></ul>"},{"i":"ae1ba55f74f4","n":131,"o":"131-9","u":"Diagnostic positif","t":"Rechercher les signes de gravité d’une chute","q":"Quelles étiologies ou situations médico-sociales rendent une chute grave chez le sujet âgé ?","a":"<p>Les signes de gravité sont liés à :</p><ul><li>Des <strong>étiologies potentiellement graves de la chute</strong> : trouble du rythme ou de la conduction cardiaque, infarctus du myocarde (IDM), accident vasculaire cérébral (AVC), pathologie infectieuse et/ou hypoglycémie.</li><li>Des <strong>situations médico-sociales à risque</strong> : la prise d'<strong>anticoagulants</strong> ou d'<strong>antiagrégants plaquettaires</strong>, un <strong>isolement socio-familial</strong> et une <strong>ostéoporose avérée</strong>.</li></ul>"},{"i":"f7fa2c16d827","n":131,"o":"131-9","u":"Diagnostic positif","t":"Rechercher les signes de gravité d’une chute","q":"Quels sont les signes de gravité liés aux conséquences directes d'une chute chez le sujet âgé ?","a":"<p>Il faut rechercher des signes de gravité tels que :</p><ul><li>Les <strong>traumatismes</strong> : contusions, plaies, luxations, fractures (notamment fracture engrenée de l'<strong>extrémité supérieure du fémur</strong>) et hémorragie intracrânienne.</li><li>Le <strong>syndrome post-chute</strong>.</li><li>Les <strong>complications de la station prolongée au sol</strong>.</li></ul>"}]};